/** Actual kinetic assembly/rotation, moving block picks, visible storage sync and native entity unload/return. */
final class MechanicalBearingRenderingTest {
    private static final BlockPos P=new BlockPos(3503,5,5),B=P.below(),D=P.east().above(),F=P.north(),R=P.east(2).above();
    private static final BlockPos LOCAL_DEPOT=new BlockPos(1,1,0),LOCAL_TANK=new BlockPos(0,0,-1);
    static void run(ClientGameTestContext context,TestSingleplayerContext world){
        var server=world.getServer();server.runCommand("gamemode spectator @p");server.runCommand("tp @p 3504.5 9 12.5");context.waitFor(client->Math.abs(client.player.getX()-3504.5)<.1&&client.level.isLoaded(P),300);
        server.runCommand("fill 3498 3 0 3512 3 15 minecraft:smooth_quartz");server.runCommand("setblock 3503 4 5 create:mechanical_bearing[facing=up]");server.runCommand("setblock 3503 5 5 minecraft:chest[facing=north]");server.runCommand("setblock 3504 5 5 minecraft:stone");server.runCommand("setblock 3505 5 5 minecraft:stone");server.runCommand("setblock 3504 6 5 create:depot");server.runCommand("setblock 3505 6 5 minecraft:barrel[facing=north]");server.runCommand("setblock 3503 5 4 create:fluid_tank");
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();((ChestBlockEntity)level.getBlockEntity(P)).setItem(0,payload());((BarrelBlockEntity)level.getBlockEntity(R)).setItem(4,payload());((FluidTankBlockEntity)level.getBlockEntity(F)).getTankInventory().fill(new com.simibubi.create.foundation.fluid.FluidStack(FluidVariant.of(Fluids.WATER),3*FluidConstants.BUCKET));try(var tx=Transaction.openOuter()){((DepotBlockEntity)level.getBlockEntity(D)).inventory.inputs.getFirst().insert(ItemVariant.of(Items.APPLE),6,tx);tx.commit();}level.addFreshEntity(new SuperGlueEntity(level,SuperGlueEntity.span(F,R)));var player=level.getServer().getPlayerList().getPlayers().getFirst();player.getInventory().clearContent();player.inventoryMenu.broadcastFullState();});
        server.runCommand("setblock 3503 3 5 create:creative_motor[facing=up]");
        var id=new AtomicReference<UUID>();var assembled=new AtomicBoolean();
        for(int i=0;i<300&&!assembled.get();i++){server.runOnServer(ignored->{var bearing=(MechanicalBearingBlockEntity)world.getConnection().getServerLevel().getBlockEntity(B);var entity=bearing.getMovedContraption();if(entity!=null&&bearing.isRunning()){if(entity.getContraption().getBlocks().size()!=6)throw new AssertionError("Bearing did not capture the whole glued structure");id.set(entity.getUUID());assembled.set(true);}});if(!assembled.get())context.waitTicks(1);}if(!assembled.get())throw new AssertionError("Actual kinetic network did not assemble bearing");
        context.waitFor(client->find(client.level,id.get())!=null&&find(client.level,id.get()).getContraption()!=null&&find(client.level,id.get()).getContraption().getBlocks().size()==6&&client.level.getBlockState(P).isAir(),400);
        context.waitFor(client->Math.abs(find(client.level,id.get()).getAngle(1))>25,200);look(context,Vec3.atCenterOf(P));world.getConnection().waitForChunksRender();context.waitTicks(5);
        context.runOnClient(client->{var entity=find(client.level,id.get());var renderer=(ContraptionEntityRenderer)client.getEntityRenderDispatcher().getRenderer(entity);var state=renderer.createRenderState(entity,.5f);if(state.blocks.size()!=6||state.blockEntities.size()<3)throw new AssertionError("Native moving block/chest/depot/tank extraction incomplete: "+state.blocks.size()+"/"+state.blockEntities.size());});screenshot(context,"create-vulkan-mechanical-bearing-rotating");
        server.runCommand("tp @p 3503.5 4 9.5");server.runCommand("gamemode survival @p");context.waitFor(client->!client.player.isSpectator()&&Math.abs(client.player.getZ()-9.5)<.1,200);look(context,Vec3.atCenterOf(P));context.waitTicks(3);
        clickMovingChest(context,id.get());
        context.waitFor(client->client.gui.screen() instanceof net.minecraft.client.gui.screens.inventory.ContainerScreen&&client.player.containerMenu instanceof ChestMenu&&same(client.player.containerMenu.getSlot(0).getItem(),7),200);clickMenu(context,0,com.mojang.blaze3d.platform.InputConstants.MOUSE_BUTTON_RIGHT);context.waitFor(client->same(client.player.containerMenu.getCarried(),4)&&same(client.player.containerMenu.getSlot(0).getItem(),3),200);clickMenu(context,27,com.mojang.blaze3d.platform.InputConstants.MOUSE_BUTTON_LEFT);context.waitFor(client->client.player.containerMenu.getCarried().isEmpty()&&same(client.player.getInventory().getItem(9),4),200);context.waitTicks(10);screenshot(context,"create-vulkan-mechanical-bearing-moving-chest-menu");context.getInput().pressKey(com.mojang.blaze3d.platform.InputConstants.KEY_ESCAPE);context.waitFor(client->client.gui.screen()==null,200);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var entity=(ControlledContraptionEntity)level.getEntity(id.get());var storage=entity.getContraption().getStorage();try(var tx=Transaction.openOuter()){if(storage.getFluids().extract(FluidVariant.of(Fluids.WATER),FluidConstants.BUCKET,tx)!=FluidConstants.BUCKET)throw new AssertionError("Moving tank extraction failed");storage.getAllItemStorages().get(LOCAL_DEPOT).extract(ItemVariant.of(Items.APPLE),2,tx);tx.commit();}});
        context.waitFor(client->{var entity=find(client.level,id.get());if(entity==null||entity.getContraption()==null)return false;var structure=entity.getContraption();return structure.getBlockEntityClientSide(LOCAL_DEPOT) instanceof DepotBlockEntity depot&&depot.getHeldItem().getCount()==4&&structure.getBlockEntityClientSide(LOCAL_TANK) instanceof FluidTankBlockEntity tank&&tank.getTankInventory().getFluidAmount()==2*FluidConstants.BUCKET;},300);
        clickMovingChest(context,id.get());context.waitFor(client->client.gui.screen()!=null&&client.player.containerMenu instanceof ChestMenu&&same(client.player.containerMenu.getSlot(0).getItem(),3),200);context.getInput().pressKey(com.mojang.blaze3d.platform.InputConstants.KEY_ESCAPE);context.waitFor(client->client.gui.screen()==null,200);
        var reload=context.computeOnClient(client->client.reloadResourcePacks());context.waitFor(client->reload.isDone()&&client.gui.overlay()==null,600);context.waitTicks(5);screenshot(context,"create-vulkan-mechanical-bearing-storage-reload");
        server.runCommand("gamemode spectator @p");server.runCommand("tp @p 5000 10 5000");var unloaded=new AtomicBoolean();for(int i=0;i<160&&!unloaded.get();i++){context.waitTicks(5);server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();unloaded.set(level.getEntity(id.get())==null&&level.getChunkSource().getChunkNow(P.getX()>>4,P.getZ()>>4)==null&&level.getChunkSource().getChunkNow(R.getX()>>4,R.getZ()>>4)==null);});}if(!unloaded.get())throw new AssertionError("Moving entity or controller retained unloaded chunks");
        server.runCommand("tp @p 3503.5 8 10.5");context.waitFor(client->find(client.level,id.get())!=null&&find(client.level,id.get()).getContraption()!=null,600);var returned=new AtomicBoolean();for(int i=0;i<300&&!returned.get();i++){server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var entity=level.getEntity(id.get());if(entity instanceof ControlledContraptionEntity moving&&moving.getContraption()!=null){var bearing=(MechanicalBearingBlockEntity)level.getBlockEntity(B);returned.set(bearing!=null&&bearing.getMovedContraption()==moving&&bearing.isRunning());if(moving.getContraption().getStorage().getAllItemStorages().get(BlockPos.ZERO).getStackInSlot(0).getCount()!=3)throw new AssertionError("Actual entity save lost changed chest contents");}});if(!returned.get())context.waitTicks(1);}if(!returned.get())throw new AssertionError("Controller failed to reattach original persisted UUID");
        look(context,Vec3.atCenterOf(P));world.getConnection().waitForChunksRender();context.waitTicks(5);screenshot(context,"create-vulkan-mechanical-bearing-unload-return");
        server.runCommand("tp @p 3503.5 4 9.5");server.runCommand("gamemode survival @p");context.waitFor(client->!client.player.isSpectator()&&Math.abs(client.player.getZ()-9.5)<.1,200);look(context,Vec3.atCenterOf(B));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(B),200);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->find(client.level,id.get())==null&&client.level.getBlockState(P).is(net.minecraft.world.level.block.Blocks.CHEST),300);
        server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();var chest=(ChestBlockEntity)level.getBlockEntity(P);if(chest==null||!same(chest.getItem(0),3))throw new AssertionError("Disassembled chest inventory differs");long fluid=0,apples=0,diamonds=chest.getItem(0).getCount();for(var pos:BlockPos.betweenClosed(P.offset(-3,0,-3),P.offset(3,2,3))){var be=level.getBlockEntity(pos);if(be instanceof FluidTankBlockEntity tank&&tank.isController())fluid+=tank.getTankInventory().getFluidAmount();if(be instanceof DepotBlockEntity depot)apples+=depot.getHeldItem().getCount();if(be instanceof BarrelBlockEntity barrel)diamonds+=barrel.getItem(4).getCount();}if(fluid!=2*FluidConstants.BUCKET||apples!=4||diamonds!=10)throw new AssertionError("Mutable storage did not survive real bearing disassembly: "+fluid+"/"+apples+"/"+diamonds);});
        var approach=new AtomicReference<BlockPos>();server.runOnServer(ignored->{var level=world.getConnection().getServerLevel();for(var side:Direction.Plane.HORIZONTAL)if(level.getBlockState(P.relative(side)).isAir()&&level.getBlockState(P.relative(side,2)).isAir()){approach.set(P.relative(side,3));break;}});if(approach.get()==null)throw new AssertionError("No unobstructed side of restored chest");var from=approach.get();server.runCommand("tp @p "+(from.getX()+.5)+" 4 "+(from.getZ()+.5));context.waitFor(client->Math.abs(client.player.getX()-from.getX()-.5)<.1&&Math.abs(client.player.getZ()-from.getZ()-.5)<.1,200);look(context,Vec3.atCenterOf(P));context.waitFor(client->client.hitResult instanceof BlockHitResult hit&&hit.getBlockPos().equals(P),200);context.waitTicks(5);context.getInput().pressKey(options->options.keyUse);context.waitFor(client->client.gui.screen()!=null&&client.player.containerMenu instanceof ChestMenu&&same(client.player.containerMenu.getSlot(0).getItem(),3),200);screenshot(context,"create-vulkan-mechanical-bearing-disassembled-inventory");context.getInput().pressKey(com.mojang.blaze3d.platform.InputConstants.KEY_ESCAPE);context.waitFor(client->client.gui.screen()==null,200);server.runCommand("gamemode spectator @p");
    }
    private static ControlledContraptionEntity find(net.minecraft.client.multiplayer.ClientLevel level,UUID uuid){if(level==null)return null;for(var entity:level.entitiesForRendering())if(entity instanceof ControlledContraptionEntity moving&&moving.getUUID().equals(uuid))return moving;return null;}
    private static void clickMovingChest(ClientGameTestContext context,UUID uuid){look(context,Vec3.atCenterOf(P));context.waitFor(client->{var entity=find(client.level,uuid);if(entity==null)return false;float angle=(entity.getAngle(1)%360+360)%360;if(angle<30||angle>65)return false;var start=client.player.getEyePosition();var end=start.add(client.player.getViewVector(1).scale(client.player.blockInteractionRange()+1));var hit=entity.rayTrace(start,end,1);return hit!=null&&hit.getBlockPos().equals(BlockPos.ZERO)&&entity.visibleFrom(start,end,hit,1);},300);context.getInput().pressKey(options->options.keyUse);}
    private static ItemStack payload(){var item=new ItemStack(Items.DIAMOND,7);item.set(DataComponents.CUSTOM_NAME,Component.literal("Rotating with Create"));return item;}
    private static boolean same(ItemStack item,int count){return item.getCount()==count&&ItemStack.isSameItemSameComponents(item,payload());}
    private static void clickMenu(ClientGameTestContext context,int index,int button){var point=context.computeOnClient(client->{var screen=client.gui.screen();var menu=(ChestMenu)client.player.containerMenu;var slot=menu.getSlot(index);float scaleX=(float)client.getWindow().getScreenWidth()/client.getWindow().getGuiScaledWidth();float scaleY=(float)client.getWindow().getScreenHeight()/client.getWindow().getGuiScaledHeight();return new Vec2(((screen.width-176)/2+slot.x+8)*scaleX,((screen.height-(114+menu.getRowCount()*18))/2+slot.y+8)*scaleY);});context.getInput().setCursorPos(point.x,point.y);context.waitTicks(2);context.getInput().pressMouse(button);}
    private static void screenshot(ClientGameTestContext context,String name){context.runOnClient(client->client.gui.hud.getChat().clearMessages(false));context.takeScreenshot(name);}
    private static void look(ClientGameTestContext context,Vec3 point){var angle=context.computeOnClient(client->{var delta=point.subtract(client.player.getEyePosition());return new Vec2((float)Math.toDegrees(Math.atan2(-delta.x,delta.z)),(float)-Math.toDegrees(Math.atan2(delta.y,Math.hypot(delta.x,delta.z))));});context.getInput().lookAt(angle.x,angle.y);}
}
